  function addNetworkLegend(atlas, host) {
    if (!host || !atlas.features?.tintLayers || !atlas.setTint) return;
    const layerOwner = 'pdNetworkTypes';
    const colors = new Map();
    const rgb = color => color.slice(1).match(/../g).map(channel => parseInt(channel, 16) / 255);
    const planned = networkTypes[0];
    const contrast = new Map(networkTypes.slice(1).flatMap(type => type.ids.map(id => [id, rgb(type.color)])));
    for (const {renderId} of atlas.objects()) {
      if (!isAdjacentNetwork(renderId) || contrast.has(renderId)) continue;
      const name = atlas.get(renderId)?.name || '';
      const type = networkTypes.find(type => type.matches?.test(name)) || networkTypes.at(-1);
      contrast.set(renderId, rgb(type.color));
    }
    for (const id of planned.ids) colors.set(id, rgb(planned.color));
    for (const [id, color] of contrast) colors.set(id, color);
    const legend = document.createElement('details');
    legend.id = 'pdNetworkLegend';
    const summary = document.createElement('summary');
    summary.textContent = 'Условные обозначения';
    legend.append(summary);

    const list = document.createElement('ul');
    list.setAttribute('aria-label', 'Условные обозначения сетей');
    for (const { name, color } of networkTypes) {
      const item = document.createElement('li');
      const swatch = document.createElement('span');
      swatch.style.backgroundColor = color;
      swatch.setAttribute('aria-hidden', 'true');
      item.append(swatch, name);
      list.append(item);
    }
    legend.append(list);

    const note = document.createElement('p');
    note.textContent = 'Цвета различают типы сетей. Метки «гл.» показывают выноски ПД.';
    legend.append(note);
    if (!showPlan) {
      const link = document.createElement('a');
      link.href = '?pdPlan=1';
      link.textContent = 'Открыть план сетей';
      legend.append(link);
    }

    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.id = 'pdNetworkColorToggle';
    toggle.textContent = 'Цвета сетей';
    toggle.setAttribute('aria-pressed', 'true');
    toggle.addEventListener('click', () => {
      const enabled = toggle.getAttribute('aria-pressed') !== 'true';
      toggle.setAttribute('aria-pressed', String(enabled));
      atlas.setTint(layerOwner, enabled ? colors : null);
    });
    host.querySelector('.pdLayerActions').prepend(toggle);
    host.append(legend);
    atlas.setTint(layerOwner, colors);
  }

  function addAdjacentDepthLabels(atlas, stage) {
    const entries = Object.entries(window.GOLUBOE_NETWORKS.adjacent_network_evidence || {})
      .filter(([id]) => id.startsWith('NET-GOL-PD-CTX-R13-DEPTH-'))
      .map(([id, source]) => ({id, source, object: atlas.get(id)}))
      .filter(({object, source}) => object?.bounds?.length === 2 && source.value);
    if (!entries.length) return () => {};
    const canvas = document.createElement('canvas');
    canvas.id = 'pdAdjacentDepthLabels';
    canvas.setAttribute('aria-hidden', 'true');
    stage.append(canvas);
    const ink = canvas.getContext('2d');
    if (!ink) return () => {};

    let frame = 0;
    function draw() {
      frame = 0;
      const section = atlas.sectionState?.();
      canvas.hidden = !adjacentNetworks || Boolean(section?.section || section?.slider?.axis);
      canvas.dataset.drawnLabels = '0';
      if (canvas.hidden) return;
      const rect = canvas.getBoundingClientRect();
      if (!rect.width || !rect.height) return;
      const ratio = Math.min(devicePixelRatio || 1, 2);
      const width = Math.round(rect.width * ratio);
      const height = Math.round(rect.height * ratio);
      if (canvas.width !== width) canvas.width = width;
      if (canvas.height !== height) canvas.height = height;
      ink.setTransform(ratio, 0, 0, ratio, 0, 0);
      ink.clearRect(0, 0, rect.width, rect.height);
      ink.font = '600 12px "Golos Text", system-ui, sans-serif';
      ink.textBaseline = 'middle';
      const obstacles = [...stage.querySelectorAll('#pdExcavationOverview,.tools,.atb-view,.stage-actions,.zoom-controls,.card-occl,.af-mk')]
        .filter(node => getComputedStyle(node).visibility !== 'hidden')
        .map(node => node.getBoundingClientRect()).filter(box => box.width && box.height);
      const hidden = new Set(atlas.hiddenState().ids);
      const isolated = atlas.isolateState();
      const selected = atlas.visibleSetState();
      const limit = matchMedia('(max-width:850px)').matches ? 3 : 6;
      let placed = 0;
      for (const {id, object, source} of entries) {
        if (!atlas.inScene(id) || hidden.has(id) || (isolated.on && !isolated.ids.includes(id)) ||
            (selected && !selected.ids.includes(id)) || !window.AtlasViewSettings.visible(object)) continue;
        const [low, high] = object.bounds;
        const point = atlas.projectToScreen(low.map((value, i) => (value + high[i]) / 2));
        if (!point?.[2]) continue;
        const x = point[0] - rect.left, y = point[1] - rect.top;
        const text = 'гл. ' + source.value;
        const w = Math.ceil(ink.measureText(text).width) + 10, h = 19;
        const box = [[8, -24], [-w - 8, -24], [8, 5], [-w - 8, 5]].find(([dx, dy]) => {
          const left = x + dx, top = y + dy;
          return left >= 3 && top >= 3 && left + w <= rect.width - 3 && top + h <= rect.height - 3 &&
            !obstacles.some(r => left + rect.left < r.right + 5 && left + rect.left + w + 5 > r.left &&
              top + rect.top < r.bottom + 5 && top + rect.top + h + 5 > r.top);
        });
        if (!box) continue;
        const left = x + box[0], top = y + box[1];
        obstacles.push({left:left+rect.left, right:left+rect.left+w, top:top+rect.top, bottom:top+rect.top+h});
        ink.strokeStyle = ink.fillStyle = '#33485d';
        ink.lineWidth = 1.5;
        ink.beginPath(); ink.moveTo(x, y); ink.lineTo(left < x ? left + w : left, top + h / 2); ink.stroke();
        ink.beginPath(); ink.arc(x, y, 3, 0, 2 * Math.PI); ink.fill();
        ink.fillStyle = '#fff';
        ink.fillRect(left, top, w, h);
        ink.strokeRect(left, top, w, h);
        ink.fillStyle = '#182d41';
        ink.fillText(text, left + 5, top + h / 2);
        if (++placed === limit) break;
      }
      canvas.dataset.drawnLabels = String(placed);
    }
    function schedule() { if (!frame) frame = requestAnimationFrame(draw); }
    for (const event of ['atlas:camera', 'atlas:visibility', 'atlas:section', 'atlas:sceneready', 'atlas:sheet', 'atlas:scope']) {
      document.addEventListener(event, schedule);
    }
    new ResizeObserver(schedule).observe(stage);
    new ResizeObserver(schedule).observe(document.getElementById('pdExcavationOverview'));
    schedule();
    return schedule;
  }

